"""In-memory record store."""

_DB = {
    "users": [{"id": 1, "name": "ada"}, {"id": 2, "name": "grace"}],
    "orders": [{"id": 10, "user_id": 1, "total": 25.0}],
}


def fetch_records(table):
    """fetch_records returns a copy of all rows in `table`."""
    if table not in _DB:
        raise KeyError(f"unknown table: {table}")
    return [dict(row) for row in _DB[table]]

"""Thin API layer over the store."""

from store import fetch_records


def list_users():
    return fetch_records("users")


def list_orders():
    return fetch_records("orders")

"""Revenue report built directly on the store (legacy path)."""

import store


def revenue_total():
    orders = store.fetch_records("orders")
    return sum(o["total"] for o in orders)

